import React, { Component } from 'react'
import Table from 'react-bootstrap/Table'
import Button from 'react-bootstrap/Button'
import Form from 'react-bootstrap/Form'
import Spinner from 'react-bootstrap/Spinner'

class CommentersTable extends Component {
    
    initialState = {
        selectedCommenters: [],
        enableCommentersSubmitButton: false
    }

    state = this.initialState
  
  
    handleChange = event => {
      
        const target = event.target;
        const value = target.checked ? target.value : '';
        //const name = target.name;
        
        if (target.checked) {
          
            this.setState({ selectedCommenters:
                    [...this.state.selectedCommenters, target.value] });
            
        } else {
          
            var selectedCommenters = selectedCommenters.filter(item => item !== target.value)
        
        }
        

        
  
    }
    
    submitForm = () => {
        this.props.handleCommentersSubmit(this.state)
        //this.setState(this.initialState)
    }
    
    
    TableHeader = () => {
        return (
          <thead>
            <tr>
              <th>Commenter</th>
              <th>Messaged Before</th>
              <th>Send Message</th>
            </tr>
          </thead>
        )
      }
      
      TableBody = props => {
        const rows = props.commenters.map((row, index) => {
          return (
            <tr key={index}>
              <td><a target='_blank' rel="noopener noreferrer" href={row.commenterUrl}>{row.commenterUrl}</a></td>
              <td></td>
              <td>
                <Form.Group>
                <Form.Check
                  type="checkbox"
                    id="" name="selectedCommenters" value={row.commenterUrl} onChange={this.handleChange}/>
                </Form.Group>
              </td>
            </tr>
          )
        })
      
        return <tbody>{rows}</tbody>
      }

    
    render() {
        
        const { commenters } = this.props
  
        const showCommentersTable = this.props.showCommentersTable ? {display: 'block'} : {display: 'none'};
        
        const showCommentersSubmitButton = this.props.showCommentersSubmitButton ? {display: 'block'} : {display: 'none'};
        const showCommentersSubmitLoadingButton = this.props.showCommentersSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
              
              
        return (
          <Form>
            <Table style={showCommentersTable}>
              <this.TableHeader />
              <this.TableBody commenters={commenters} />
            </Table>
            
             <Button type="submit" value="Submit" onClick={e => {e.preventDefault(); this.submitForm()}} style={showCommentersSubmitButton}>Submit</Button>
                  
                    <Button variant="primary" disabled style={showCommentersSubmitLoadingButton}>
                      <Spinner
                        as="span"
                        animation="grow"
                        size="sm"
                        role="status"
                        aria-hidden="true"
                      />
                      Loading...
                    </Button>
                    
          </Form>
        )
    }

}

export default CommentersTable;
